    {
        if (ContienePersonaNoAutorizada(respuesta, idsPersonasAutorizadas, directorio))
        {
            return new SalidaVerificada(Textos.Negativa(usuario.Rol), [Textos.CitaNegativa()], ResultadoAuditoria.FugaBloqueada);
