using System.Globalization;
using System.Net;
using System.Text.Encodings.Web;
using Microsoft.Extensions.Options;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Infrastructure.ApiAcademica;
using TutorFlow.Infrastructure.Auditoria;
using TutorFlow.Infrastructure.Conocimiento;
using TutorFlow.Infrastructure.Llm;
using TutorFlow.Infrastructure.Tiempo;

namespace TutorFlow.Api;

public static class ServiciosTutorFlow
{
    private const string NombreClienteLlm = "llm";
    private const string SeccionCodigosAsignatura = "Autorizacion:CodigosAsignatura";
    private const string ClaveMarcadorCanario = "Llm:MarcadorCanario";
    private const string ClaveSeccionLimites = "Limites";

    public static IServiceCollection AgregarTutorFlow(this IServiceCollection servicios, IConfiguration configuracion)
    {
        AgregarOpciones(servicios);
        AgregarNucleo(servicios, configuracion);
        AgregarInfraestructura(servicios, configuracion);
        AgregarLlm(servicios, configuracion);
        servicios.AddProblemDetails();
        servicios.AddExceptionHandler<ManejadorExcepciones>();
        servicios.ConfigureHttpJsonOptions(opciones => opciones.SerializerOptions.Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping);
        servicios.AddHostedService<RegistroArranqueLlm>();
        return servicios;
    }

    private static void AgregarOpciones(IServiceCollection servicios)
    {
        servicios.AddOptions<OpcionesApiAcademica>()
            .BindConfiguration(OpcionesApiAcademica.Seccion)
            .Validate(o => Uri.IsWellFormedUriString(o.UrlBase, UriKind.Absolute), "ApiAcademica:UrlBase debe ser una URL absoluta")
            .ValidateOnStart();
        servicios.AddOptions<OpcionesLlm>()
            .BindConfiguration(OpcionesLlm.Seccion)
            .Validate(o => o.Proveedores.Count > 0, "Llm:Proveedores no puede estar vacio")
            .ValidateOnStart();
        servicios.AddOptions<LimitesAsistente>()
            .BindConfiguration(ClaveSeccionLimites)
            .Validate(l => l.MaximoCaracteresPregunta > 0 && l.PreguntasPorMinutoPorIp > 0, "Limites invalidos")
            .ValidateOnStart();
        servicios.AddOptions<OpcionesConocimiento>()
            .BindConfiguration(OpcionesConocimiento.Seccion)
            .Validate(o => o.DocumentosVigentes.Count > 0, "Conocimiento:DocumentosVigentes no puede estar vacio")
            .ValidateOnStart();
    }

    private static void AgregarNucleo(IServiceCollection servicios, IConfiguration configuracion)
    {
        servicios.AddSingleton(proveedor => proveedor.GetRequiredService<IOptions<LimitesAsistente>>().Value);
        servicios.AddSingleton<PoliticaAcceso>();
        servicios.AddSingleton<VerificadorSalida>();
        servicios.AddSingleton<AuditorPeticiones>();
        servicios.AddSingleton<PresupuestoDiario>();
        servicios.AddSingleton<LimitadorIdentidades>();
        servicios.AddSingleton(proveedor => new LimitadorTasaPorIp(
            proveedor.GetRequiredService<LimitesAsistente>().PreguntasPorMinutoPorIp,
            TimeSpan.FromMinutes(1),
            TimeProvider.System));
        servicios.AddSingleton(proveedor => ConfiguracionDelAsistente(proveedor, configuracion));
        servicios.AddScoped<PreguntarAsistente>();
        servicios.AddScoped<ProcesadorPregunta>();
    }

    private static void AgregarInfraestructura(IServiceCollection servicios, IConfiguration configuracion)
    {
        servicios.AddSingleton<IReloj, RelojSistema>();
        servicios.AddSingleton(proveedor => new ArchivoAuditoriaDiario(
            configuracion[ArchivoAuditoriaDiario.ClaveRuta],
            proveedor.GetRequiredService<IReloj>()));
        servicios.AddSingleton<IAuditoria, AuditoriaJsonConsola>();
        servicios.AddSingleton<IBaseConocimiento>(proveedor =>
            CargadorConocimiento.Cargar(proveedor.GetRequiredService<IOptions<OpcionesConocimiento>>().Value));
        servicios.AddHttpClient<IApiAcademica, ClienteApiAcademica>((proveedor, cliente) =>
            {
                var opciones = proveedor.GetRequiredService<IOptions<OpcionesApiAcademica>>().Value;
                cliente.BaseAddress = new Uri(opciones.UrlBase.TrimEnd('/') + "/");
                cliente.Timeout = TimeSpan.FromSeconds(proveedor.GetRequiredService<LimitesAsistente>().PresupuestoApiAcademicaSegundos);
            })
            .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { AllowAutoRedirect = false });
    }

    private static void AgregarLlm(IServiceCollection servicios, IConfiguration configuracion)
    {
        servicios.AddSingleton(proveedor => ResolutorProveedorLlm.Resolver(
            EntornoDesde(configuracion),
            proveedor.GetRequiredService<IOptions<OpcionesLlm>>().Value));
        servicios.AddHttpClient(NombreClienteLlm)
            .ConfigureHttpClient((proveedor, cliente) =>
                cliente.Timeout = TimeSpan.FromSeconds(proveedor.GetRequiredService<LimitesAsistente>().TimeoutLlmSegundos));
        servicios.AddScoped<IClienteLlm>(proveedor => FabricaClienteLlm.Crear(
            proveedor.GetRequiredService<ProveedorResuelto>(),
            configuracion["LLM_API_KEY"],
            proveedor.GetRequiredService<IHttpClientFactory>().CreateClient(NombreClienteLlm)));
    }

    private static EntornoLlm EntornoDesde(IConfiguration configuracion) => new(
        configuracion["LLM_API_KEY"],
        configuracion["LLM_PROVEEDOR"],
        configuracion["LLM_URL_BASE"],
        configuracion["LLM_MODELO"],
        LeerDecimal(configuracion["LLM_PRECIO_ENTRADA"]),
        LeerDecimal(configuracion["LLM_PRECIO_SALIDA"]));

    private static decimal? LeerDecimal(string? valor) =>
        decimal.TryParse(valor, NumberStyles.Number, CultureInfo.InvariantCulture, out var numero) ? numero : null;

    private static ConfiguracionAsistente ConfiguracionDelAsistente(IServiceProvider proveedor, IConfiguration configuracion)
    {
        var resuelto = proveedor.GetRequiredService<ProveedorResuelto>();
        var precio = resuelto.PrecioDesconocido ? null : new PrecioModelo(resuelto.PrecioEntradaPorMillon, resuelto.PrecioSalidaPorMillon);
        var codigos = configuracion.GetSection(SeccionCodigosAsignatura).Get<string[]>() ?? [];
        return new ConfiguracionAsistente(precio, configuracion[ClaveMarcadorCanario], codigos);
    }
}
using System.Diagnostics;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api;

public sealed partial class ProcesadorPregunta
{
    private const string TituloSolicitudInvalida = "La solicitud no es válida.";
    private const string TituloCuerpoDemasiadoGrande = "El cuerpo de la solicitud supera el tamaño permitido.";
    private const string TituloDemasiadasSolicitudes = "Se superó el límite de preguntas. Intenta de nuevo más tarde.";
    private const string TituloServicioNoDisponible = "El servicio no está disponible en este momento. Intenta de nuevo.";

    private readonly LimitesAsistente _limites;
    private readonly LimitadorTasaPorIp _limitadorTasa;
    private readonly LimitadorIdentidades _limitadorIdentidades;
    private readonly AuditorPeticiones _auditor;
    private readonly PreguntarAsistente _preguntarAsistente;
    private readonly ILogger<ProcesadorPregunta> _logger;

    public ProcesadorPregunta(
        LimitesAsistente limites,
        LimitadorTasaPorIp limitadorTasa,
        LimitadorIdentidades limitadorIdentidades,
        AuditorPeticiones auditor,
        PreguntarAsistente preguntarAsistente,
        ILogger<ProcesadorPregunta> logger)
    {
        _limites = limites;
        _limitadorTasa = limitadorTasa;
        _limitadorIdentidades = limitadorIdentidades;
        _auditor = auditor;
        _preguntarAsistente = preguntarAsistente;
        _logger = logger;
    }

    public async Task<IResult> ProcesarAsync(HttpContext contexto, CancellationToken cancellationToken)
    {
        var peticion = new DatosPeticion(IpDe(contexto), contexto.TraceIdentifier, Stopwatch.StartNew());
        var tasa = _limitadorTasa.Intentar(peticion.Ip);
        if (!tasa.Permitido)
        {
            return Rechazar429(contexto, peticion, null, tasa.SegundosParaReintentar);
        }

        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
        if (cuerpo.ExcedeElLimite)
        {
            return RechazarInvalida(peticion, null, StatusCodes.Status413PayloadTooLarge, TituloCuerpoDemasiadoGrande);
        }

        var solicitud = ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
        return solicitud.EsValida
            ? await ResponderAsync(contexto, peticion, solicitud, cancellationToken)
            : RechazarInvalida(peticion, solicitud.Pregunta, StatusCodes.Status400BadRequest, TituloSolicitudInvalida);
    }

    private static string IpDe(HttpContext contexto)
    {
        var direccion = contexto.Connection.RemoteIpAddress;
        if (direccion is null)
        {
            return "desconocida";
        }

        return (direccion.IsIPv4MappedToIPv6 ? direccion.MapToIPv4() : direccion).ToString();
    }

    private async Task<IResult> ResponderAsync(HttpContext contexto, DatosPeticion peticion, SolicitudValidada solicitud, CancellationToken cancellationToken)
    {
        var usuario = new Usuario(solicitud.Rol!.Value, solicitud.UsuarioId!);
        var identidades = _limitadorIdentidades.Registrar(peticion.Ip, usuario.Id);
        if (identidades.SuperacionNueva)
        {
            _auditor.RegistrarMultiplesIdentidades(peticion.Ip, identidades.Ids);
        }

        if (identidades.Superado && _limites.BloquearMultiplesIdentidades)
        {
            return Rechazar429(contexto, peticion, solicitud, (int)TimeSpan.FromMinutes(_limites.VentanaIdentidadesMinutos).TotalSeconds);
        }

        return await PreguntarAsync(peticion, new PreguntaEntrada(solicitud.Pregunta!, usuario), cancellationToken);
    }

    private async Task<IResult> PreguntarAsync(DatosPeticion peticion, PreguntaEntrada entrada, CancellationToken cancellationToken)
    {
        try
        {
            var resultado = await _preguntarAsistente.EjecutarAsync(entrada, peticion.Ip, peticion.CorrelationId, cancellationToken);
            return Mapear(resultado);
        }
        catch (Exception excepcion) when (EsFalloDeDependencia(excepcion, cancellationToken))
        {
            RegistrarDependenciaCaida(_logger, excepcion.GetType().Name);
            RegistrarError(peticion, entrada);
            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
        }
        catch (Exception)
        {
            RegistrarError(peticion, entrada);
            throw;
        }
    }

    private static bool EsFalloDeDependencia(Exception excepcion, CancellationToken cancellationToken) =>
        excepcion is DependenciaNoDisponibleException or HttpRequestException or TimeoutException
        || (excepcion is OperationCanceledException && !cancellationToken.IsCancellationRequested);

    private void RegistrarError(DatosPeticion peticion, PreguntaEntrada entrada) =>
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            entrada.Usuario.Rol,
            entrada.Usuario.Id,
            entrada.Pregunta,
            ResultadoAuditoria.Error,
            peticion.Cronometro.ElapsedMilliseconds));

    private static IResult Mapear(ResultadoPregunta resultado)
    {
        if (resultado.Respuesta is not { } respuesta)
        {
            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
        }

        var cuerpo = new PreguntaRespuesta(
            respuesta.Respuesta,
            [.. respuesta.Citas.Select(cita => new CitaRespuesta(cita.Documento, cita.Seccion))],
            respuesta.UsoDatosEstudiante,
            respuesta.Tokens,
            respuesta.CostoUsd);
        var estado = resultado.Tipo == TipoResultadoPregunta.Denegada ? StatusCodes.Status403Forbidden : StatusCodes.Status200OK;
        return Results.Json(cuerpo, statusCode: estado);
    }

    private IResult RechazarInvalida(DatosPeticion peticion, string? pregunta, int estado, string titulo)
    {
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            null,
            null,
            pregunta,
            ResultadoAuditoria.Invalida,
            peticion.Cronometro.ElapsedMilliseconds));
        return Results.Problem(statusCode: estado, title: titulo);
    }

    private IResult Rechazar429(HttpContext contexto, DatosPeticion peticion, SolicitudValidada? solicitud, int segundosParaReintentar)
    {
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
