cd backend/src; node -e '
const fs=require("fs"),path=require("path");
function walk(d){return fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?(["obj","bin"].includes(e.name)?[]:walk(path.join(d,e.name))):e.name.endsWith(".cs")?[path.join(d,e.name)]:[]);}
for(const f of walk(".")){const L=fs.readFileSync(f,"utf8").split("\n");for(let i=0;i<L.length;i++){const m=L[i].match(/^\s{4}(public|private|internal|protected)[^=;]*\)\s*$/);if(m&&L[i+1]&&L[i+1].trim()==="{"){let j=i+2,depth=1;while(j<L.length&&depth>0){depth+=(L[j].match(/\{/g)||[]).length-(L[j].match(/\}/g)||[]).length;j++;}const n=j-i;if(n>21)console.log(f,i+1,n,L[i].trim().slice(0,70));}}}'

